/** Lower-cases text and turns every run of punctuation and spaces into one space, for matching. */
export function normaliseText(text) {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

/** Returns a title as librarians file it: without a leading 'The', 'A' or 'An' (a title that is only an article stays whole). */
export function filingTitle(title) {
  const trimmed = title.trim();
  const filed = trimmed.replace(/^(?:the|an?)\s+/i, '');
  return filed === '' ? trimmed : filed;
}

/** Replaces each {name} in a template by the value of that name; unknown names stay as they are. */
export function fillTemplate(template, values) {
  return template.replace(/\{(\w+)\}/g, (placeholder, name) =>
    name in values ? String(values[name]) : placeholder,
  );
}

