  const titled = (title) => ({ id: title, title, author: 'x' });
  const titles = ['Theory of Games', 'The', 'An Ant', 'Anthem', 'a Bee'].map(titled);
  assert.deepEqual(
    searchCatalog(titles, 'x').map((item) => item.title),
    ['An Ant', 'Anthem', 'a Bee', 'The', 'Theory of Games'],
  );
});

test('finds nothing for an empty query', () => {
  assert.deepEqual(searchCatalog(items, '  '), []);
});

